/*
 * Rotating home-page banner. Fades between photos listed in gallery-manifest.json (generated by
 * deployConfiguratorAssets.ps1 from docs/images/gallery/ - see CONTEXT.md / DEVELOPMENT.md).
 * Uses two stacked <img> elements and crossfades their opacity so the next photo is fully loaded
 * before it's swapped in, rather than a single <img> whose src changes underneath a fade-out.
 */

const ROTATE_INTERVAL_MS = 5000;

async function loadGalleryPhotos() {
  try {
    const response = await fetch("./js/data/gallery-manifest.json");
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return await response.json();
  } catch (err) {
    console.warn("Could not load gallery-manifest.json (run deployConfiguratorAssets.ps1 to generate it).", err);
    return [];
  }
}

/** Combines optional location/year into "Location, Year" / "Location" / "Year" / "" as available. */
function formatMeta(photo) {
  return [photo.location, photo.year].filter(Boolean).join(", ");
}

function showPhoto(img, captionEl, metaEl, photo) {
  img.src = `./images/gallery/${photo.file}`;
  img.alt = photo.caption;
  captionEl.textContent = photo.caption;
  const meta = formatMeta(photo);
  metaEl.textContent = meta;
  metaEl.hidden = !meta;
  img.classList.add("visible");
}

async function init() {
  const banner = document.getElementById("galleryBanner");
  if (!banner) return;

  const photos = await loadGalleryPhotos();
  if (!photos.length) return;

  const imgA = banner.querySelector(".gallery-banner-image.a");
  const imgB = banner.querySelector(".gallery-banner-image.b");
  const captionEl = document.getElementById("galleryCaption");
  const metaEl = document.getElementById("galleryMeta");

  let index = 0;
  let showingA = true;
  showPhoto(imgA, captionEl, metaEl, photos[index]);

  if (photos.length === 1) return;

  setInterval(() => {
    index = (index + 1) % photos.length;
    const nextImg = showingA ? imgB : imgA;
    const prevImg = showingA ? imgA : imgB;
    showPhoto(nextImg, captionEl, metaEl, photos[index]);
    prevImg.classList.remove("visible");
    showingA = !showingA;
  }, ROTATE_INTERVAL_MS);
}

init();
